"use strict";
// Tek dosya sürüm: site dosyaları ve resimler EMBED içine gömülüdür (düzenlemeyin).
var EMBED = {"/admin.html": [".html", ""], "/style.css": [".css", ""], "/index.html": [".html", ""], "/script.js": [".js", ""], "/sablon.xlsx": [".xlsx", ""], "/images/fill.png": [".png", ""], "/images/i1.png": [".png", ""], "/images/i3.png": [".png", ""], "/images/parts.png": [".png", ""], "/images/hero.jpg": [".jpg", ""], "/images/logo.png": [".png", ""], "/images/car.png": [".png", ""], "/images/servo.png": [".png", ""], "/images/b2.png": [".png", ""], "/images/pump.png": [".png", ""], "/images/i2.png": [".png", ""], "/images/fright.png": [".png", ""], "/images/flogo.png": [".png", ""], "/images/b3.png": [".png", ""], "/images/kit.png": [".png", ""], "/images/b1.png": [".png", ""], "/images/i4.png": [".png", ""]};
// FrenServosu.com – bağımlılıksız Node.js sunucusu (Node 20+)
const http = require("http"), fs = require("fs"), path = require("path"), crypto = require("crypto");
const PORT = +process.env.PORT || 3000;
const ADMIN = process.env.ADMIN_PASSWORD || "";
const BANK = process.env.BANK_INFO || "";
const ROOT = path.join(__dirname, "public");
const DBF = process.env.DB_FILE || path.join(__dirname, "data", "db.json");
const CATS = ["servo", "pompa", "kit", "diger"];
const STATUS = ["yeni", "hazirlaniyor", "kargoda", "teslim", "iptal"];

const C = (brand, model = "", from = 0, to = 0, engine = "", gear = "") => ({ brand, model, from, to, engine, gear });
const S = (id, c, n, no, p, compat) => ({ id, c, n, no, p, compat, stock: 20, active: true });
const SEED = [
  S(1, "servo", "Fren Servosu 9\" Tek Diyaframlı", "FS-1001", 3450, [C("Volkswagen", "Golf", 2013, 2020, "1.6 TDI", "Manuel"), C("Volkswagen", "Golf", 2013, 2020, "1.4 TSI"), C("Audi", "A3", 2015, 2020)]),
  S(2, "servo", "Fren Servosu 10\" Çift Diyaframlı", "FS-1002", 4200, [C("Renault", "Clio", 2012, 2019), C("Dacia", "Duster", 2014, 2023, "1.5 dCi")]),
  S(3, "servo", "Fren Servosu Ana Merkez Dahil", "FS-1003", 5100, [C("Fiat", "Egea", 2015, 2023), C("Ford", "Focus", 2011, 2018, "1.5 TDCi")]),
  S(4, "pompa", "Vakum Pompası Elektrikli", "VP-2001", 2750, [C("Audi", "A4", 2016, 2022, "2.0 TDI"), C("Volkswagen", "Passat", 2015, 2022)]),
  S(5, "pompa", "Vakum Pompası Mekanik", "VP-2002", 1890, [C("Ford", "Focus", 2011, 2018), C("Renault", "Megane", 2016, 2022, "1.5 dCi")]),
  S(6, "kit", "Servo Tamir Kiti (Diyafram+Conta)", "TK-3001", 690, [C("Fiat", "Egea", 2015, 2023), C("Volkswagen", "Golf", 2013, 2020), C("Renault", "Clio", 2012, 2019)]),
  S(7, "kit", "Servo Valf ve Conta Seti", "TK-3002", 420, [C("Ford", "Focus", 2011, 2018), C("Audi", "A3", 2015, 2020)]),
  S(8, "diger", "Servo Vakum Hortumu", "DP-4001", 260, ["Volkswagen", "Fiat", "Ford", "Audi", "Renault", "Dacia"].map(b => C(b))),
  S(9, "diger", "Çek Valf", "DP-4002", 150, ["Renault", "Dacia", "Fiat"].map(b => C(b)))
];
const DEF_SET = { firma: "FrenServosu.com", telefon: "", whatsapp: "", email: "", adres: "", saat: "", banka: "" };

let db;
function save() {
  fs.mkdirSync(path.dirname(DBF), { recursive: true });
  const t = DBF + ".tmp";
  fs.writeFileSync(t, JSON.stringify(db, null, 1));
  fs.renameSync(t, DBF);
}
try { db = JSON.parse(fs.readFileSync(DBF, "utf8")); }
catch (e) { db = { products: SEED, orders: [], nextId: SEED.length + 1, settings: { ...DEF_SET } }; save(); }
db.settings = { ...DEF_SET, ...(db.settings || {}) };
db.products.forEach(p => { if (!Array.isArray(p.compat)) p.compat = (p.v || []).map(b => C(b)); delete p.v; if (!Array.isArray(p.oem)) p.oem = []; if (typeof p.desc !== "string") p.desc = ""; });

const send = (res, code, obj, h = {}) => {
  res.writeHead(code, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...h });
  res.end(JSON.stringify(obj));
};
const fail = (code, msg) => Object.assign(new Error(msg), { code });
const readBody = (req, max = 1e5) => new Promise((ok, no) => {
  let d = "", n = 0;
  req.on("data", c => { n += c.length; if (n > max) { no(fail(413, "İstek çok büyük")); req.destroy(); } else d += c; });
  req.on("end", () => { try { ok(d ? JSON.parse(d) : {}); } catch (e) { no(fail(400, "Geçersiz JSON")); } });
  req.on("error", no);
});
const ip = req => String(req.headers["x-forwarded-for"] || req.socket.remoteAddress || "").split(",")[0].trim();

// ---- admin oturumu ----
const sess = new Map(), fails = new Map();
const cookie = req => { const m = /(?:^|;\s*)sid=([a-f0-9]{48})/.exec(req.headers.cookie || ""); return m && m[1]; };
const authed = req => { const t = cookie(req), e = t && sess.get(t); if (e && e > Date.now()) return true; if (t) sess.delete(t); return false; };
const same = (a, b) => crypto.timingSafeEqual(crypto.createHash("sha256").update(a).digest(), crypto.createHash("sha256").update(b).digest());

const str = (x, n) => String(x == null ? "" : x).trim().slice(0, n);
const oemList = a => [...new Set((Array.isArray(a) ? a : String(a == null ? "" : a).split(/[,;\n]+/)).map(x => str(x, 40)).filter(Boolean))].slice(0, 50);
const yr = x => { const n = Math.round(Number(x)); return n >= 1950 && n <= 2100 ? n : 0; };
function cleanCompat(a) {
  if (!Array.isArray(a)) return [];
  return a.slice(0, 500).map(r => {
    const o = { brand: str(r && r.brand, 40), model: str(r && r.model, 40), from: yr(r && r.from), to: yr(r && r.to), engine: str(r && r.engine, 40), gear: str(r && r.gear, 40) };
    if (o.from && o.to && o.from > o.to) [o.from, o.to] = [o.to, o.from];
    return o;
  }).filter(r => r.brand);
}
function cleanProduct(b) {
  const n = String(b.n || "").trim(), no = String(b.no || "").trim(), p = Number(b.p), stock = Number(b.stock);
  if (n.length < 2 || n.length > 120) return "Ürün adı 2-120 karakter olmalı";
  if (!no || no.length > 40) return "Parça numarası gerekli";
  if (!CATS.includes(b.c)) return "Geçersiz kategori";
  if (!(p >= 0 && p < 1e7)) return "Geçersiz fiyat";
  if (!Number.isInteger(stock) || stock < 0 || stock > 1e5) return "Geçersiz stok";
  return { n, no, c: b.c, p: Math.round(p * 100) / 100, stock, compat: cleanCompat(b.compat), oem: oemList(b.oem), desc: str(b.desc, 1000), active: b.active !== false };
}
function parseNum(x) {
  if (typeof x === "number") return x;
  let s = String(x == null ? "" : x).replace(/[^\d.,-]/g, "");
  if (s.includes(",")) s = s.replace(/\./g, "").replace(",", ".");
  return s === "" ? NaN : Number(s);
}
function catKey(x) {
  const s = String(x || "").toLocaleLowerCase("tr");
  if (CATS.includes(s)) return s;
  if (/servo/.test(s)) return "servo";
  if (/pompa|vakum/.test(s)) return "pompa";
  if (/tamir|kit/.test(s)) return "kit";
  if (/di[gğ]er|par[cç]a/.test(s)) return "diger";
  return "";
}
function importRows(rows) {
  if (!Array.isArray(rows) || !rows.length || rows.length > 20000) throw fail(400, "Satır sayısı 1 ile 20000 arasında olmalı");
  const g = new Map(), errors = [];
  rows.forEach((r, i) => {
    const line = i + 2, no = str(r && r.no, 40);
    if (!no) { errors.push("Satır " + line + ": Parça No boş"); return; }
    let x = g.get(no);
    if (!x) { x = { no, n: "", c: "", p: NaN, stock: NaN, active: null, compat: [], oem: [], desc: "" }; g.set(no, x); }
    if (!x.n && r.name) x.n = str(r.name, 120);
    if (!x.c && r.cat) { x.c = catKey(r.cat); if (!x.c) errors.push("Satır " + line + " (" + no + "): Kategori anlaşılamadı: " + str(r.cat, 30)); }
    if (isNaN(x.p) && r.price !== "" && r.price != null) x.p = parseNum(r.price);
    if (isNaN(x.stock) && r.stock !== "" && r.stock != null) x.stock = Math.round(parseNum(r.stock));
    if (x.active === null && r.active !== "" && r.active != null) x.active = !/^(hay[ıi]r|0|false|h)$/.test(String(r.active).trim().toLocaleLowerCase("tr"));
    if (r.oem) oemList(r.oem).forEach(o => { if (!x.oem.includes(o)) x.oem.push(o); });
    if (!x.desc && r.desc) x.desc = str(r.desc, 1000);
    if (r.brand) x.compat.push({ brand: r.brand, model: r.model, from: r.from, to: r.to, engine: r.engine, gear: r.gear });
  });
  let added = 0, updated = 0;
  for (const [no, x] of g) {
    const ex = db.products.find(p => p.no === no);
    const m = { n: x.n || (ex && ex.n), no, c: x.c || (ex && ex.c), p: isNaN(x.p) ? (ex ? ex.p : NaN) : x.p, stock: isNaN(x.stock) ? (ex ? ex.stock : 0) : x.stock, compat: x.compat.length ? x.compat : (ex ? ex.compat : []), oem: x.oem.length ? x.oem : (ex ? ex.oem : []), desc: x.desc || (ex ? ex.desc : ""), active: x.active === null ? (ex ? ex.active : true) : x.active };
    const c = cleanProduct(m);
    if (typeof c === "string") { errors.push(no + ": " + c); continue; }
    if (ex) { Object.assign(ex, c); updated++; } else { db.products.push({ id: db.nextId++, ...c }); added++; }
  }
  if (added || updated) save();
  return { added, updated, errorCount: errors.length, errors: errors.slice(0, 40) };
}

function createOrder(b) {
  const name = String(b.name || "").trim(), address = String(b.address || "").trim();
  const phone = String(b.phone || "").replace(/[^\d+]/g, "");
  if (name.length < 2 || name.length > 80) throw fail(400, "Ad soyad 2-80 karakter olmalı");
  if (!/^\+?\d{10,13}$/.test(phone)) throw fail(400, "Geçerli bir telefon numarası girin");
  if (address.length < 10 || address.length > 300) throw fail(400, "Adres 10-300 karakter olmalı");
  if (!["havale", "kapida"].includes(b.pay)) throw fail(400, "Ödeme yöntemi seçin");
  if (!Array.isArray(b.items) || !b.items.length || b.items.length > 50) throw fail(400, "Sepet boş");
  const want = new Map();
  for (const it of b.items) {
    const id = Number(it && it.id), q = Number(it && it.q);
    if (!Number.isInteger(id) || !Number.isInteger(q) || q < 1 || q > 20) throw fail(400, "Geçersiz ürün miktarı");
    want.set(id, (want.get(id) || 0) + q);
  }
  const lines = [];
  for (const [id, q] of want) {
    const p = db.products.find(x => x.id === id && x.active);
    if (!p) throw fail(409, "Sepetteki bir ürün artık satışta değil");
    if (p.stock < q) throw fail(409, p.n + " için yeterli stok yok (kalan: " + p.stock + ")");
    lines.push({ id, n: p.n, no: p.no, p: p.p, q });
  }
  lines.forEach(l => { db.products.find(x => x.id === l.id).stock -= l.q; });
  const total = Math.round(lines.reduce((s, l) => s + l.p * l.q, 0) * 100) / 100;
  const o = { no: "FS" + Date.now().toString(36).toUpperCase() + crypto.randomBytes(1).toString("hex").toUpperCase(), date: new Date().toISOString(), name, phone, address, pay: b.pay, lines, total, status: "yeni" };
  db.orders.unshift(o);
  save();
  return o;
}

async function api(req, res, p) {
  const m = req.method;
  if (m === "GET" && p === "/api/products") return send(res, 200, db.products.filter(x => x.active).map(({ id, c, n, no, p, compat, stock, oem, desc }) => ({ id, c, n, no, p, compat, stock, oem, desc })));
  if (m === "GET" && p === "/api/settings") { const { firma, telefon, whatsapp, email, adres, saat } = db.settings; return send(res, 200, { firma, telefon, whatsapp, email, adres, saat }); }
  if (m === "POST" && p === "/api/orders") {
    const o = createOrder(await readBody(req));
    return send(res, 201, { no: o.no, total: o.total, pay: o.pay, bank: o.pay === "havale" ? (db.settings.banka || BANK) : "" });
  }
  if (m === "POST" && p === "/api/admin/login") {
    if (!ADMIN) throw fail(503, "ADMIN_PASSWORD ayarlanmamış");
    const k = ip(req), f = fails.get(k) || { n: 0, t: Date.now() };
    if (Date.now() - f.t > 6e5) { f.n = 0; f.t = Date.now(); }
    if (f.n >= 5) throw fail(429, "Çok fazla deneme. 10 dakika sonra tekrar deneyin");
    const b = await readBody(req);
    if (!same(String(b.password || ""), ADMIN)) { f.n++; fails.set(k, f); throw fail(401, "Şifre hatalı"); }
    const t = crypto.randomBytes(24).toString("hex");
    sess.set(t, Date.now() + 8 * 36e5);
    const sec = req.headers["x-forwarded-proto"] === "https" ? "; Secure" : "";
    return send(res, 200, { ok: true }, { "Set-Cookie": "sid=" + t + "; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800" + sec });
  }
  if (!p.startsWith("/api/admin/")) throw fail(404, "Bulunamadı");
  if (!authed(req)) throw fail(401, "Giriş gerekli");
  if (m !== "GET" && !/^application\/json/.test(req.headers["content-type"] || "")) throw fail(415, "JSON gerekli");
  if (m === "POST" && p === "/api/admin/logout") { sess.delete(cookie(req)); return send(res, 200, { ok: true }); }
  if (m === "GET" && p === "/api/admin/settings") return send(res, 200, db.settings);
  if (m === "PUT" && p === "/api/admin/settings") {
    const b = await readBody(req), L = { firma: 80, telefon: 30, whatsapp: 30, email: 80, adres: 300, saat: 120, banka: 500 };
    for (const k in L) db.settings[k] = str(b[k], L[k]);
    save(); return send(res, 200, db.settings);
  }
  if (m === "POST" && p === "/api/admin/import") return send(res, 200, importRows((await readBody(req, 8e6)).rows));
  if (m === "GET" && p === "/api/admin/products") return send(res, 200, db.products);
  if (m === "GET" && p === "/api/admin/orders") return send(res, 200, db.orders);
  if (m === "POST" && p === "/api/admin/products") {
    const c = cleanProduct(await readBody(req)); if (typeof c === "string") throw fail(400, c);
    const x = { id: db.nextId++, ...c }; db.products.push(x); save(); return send(res, 201, x);
  }
  let r = /^\/api\/admin\/products\/(\d+)$/.exec(p);
  if (r) {
    const i = db.products.findIndex(x => x.id === +r[1]); if (i < 0) throw fail(404, "Ürün yok");
    if (m === "PUT") { const c = cleanProduct(await readBody(req)); if (typeof c === "string") throw fail(400, c); db.products[i] = { id: +r[1], ...c }; save(); return send(res, 200, db.products[i]); }
    if (m === "DELETE") { db.products.splice(i, 1); save(); return send(res, 200, { ok: true }); }
  }
  r = /^\/api\/admin\/orders\/(FS[A-Z0-9]+)$/.exec(p);
  if (r && m === "PATCH") {
    const o = db.orders.find(x => x.no === r[1]); if (!o) throw fail(404, "Sipariş yok");
    const s = (await readBody(req)).status; if (!STATUS.includes(s)) throw fail(400, "Geçersiz durum");
    if (s === "iptal" && o.status !== "iptal") o.lines.forEach(l => { const q = db.products.find(x => x.id === l.id); if (q) q.stock += l.q; });
    if (o.status === "iptal" && s !== "iptal") o.lines.forEach(l => { const q = db.products.find(x => x.id === l.id); if (q) q.stock = Math.max(0, q.stock - l.q); });
    o.status = s; save(); return send(res, 200, o);
  }
  throw fail(404, "Bulunamadı");
}

const MIME = { ".html": "text/html; charset=utf-8", ".css": "text/css; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".png": "image/png", ".jpg": "image/jpeg", ".svg": "image/svg+xml", ".ico": "image/x-icon", ".txt": "text/plain; charset=utf-8", ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" };
const FILES = Object.fromEntries(Object.entries(EMBED).map(([k, v]) => [k, [v[0], Buffer.from(v[1], "base64")]]));
function serve(req, res, p) {
  if (req.method !== "GET" && req.method !== "HEAD") throw fail(405, "İzin yok");
  if (p === "/") p = "/index.html"; else if (p === "/admin") p = "/admin.html";
  const f = FILES[p];
  if (!f) { res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" }); return res.end("Sayfa bulunamadı"); }
  res.writeHead(200, { "Content-Type": MIME[f[0]] || "application/octet-stream", "Content-Length": f[1].length, "Cache-Control": /^\.(html|css|js)$/.test(f[0]) ? "no-cache" : "public, max-age=3600", ...(f[0] === ".xlsx" ? { "Content-Disposition": 'attachment; filename="urun-sablonu.xlsx"' } : {}) });
  res.end(req.method === "HEAD" ? undefined : f[1]);
}

http.createServer(async (req, res) => {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "SAMEORIGIN");
  res.setHeader("Referrer-Policy", "same-origin");
  const p = (req.url || "/").split("?")[0];
  try {
    if (p === "/healthz") return send(res, 200, { ok: true });
    if (p.startsWith("/api/")) return await api(req, res, p);
    serve(req, res, p);
  } catch (e) {
    if (!e.code || typeof e.code !== "number") console.error(e);
    send(res, typeof e.code === "number" ? e.code : 500, { error: typeof e.code === "number" ? e.message : "Sunucu hatası" });
  }
}).listen(PORT, () => console.log("FrenServosu çalışıyor: http://localhost:" + PORT + (ADMIN ? "" : "  (uyarı: ADMIN_PASSWORD yok, yönetim paneli kapalı)")));
